/* ---------- Derived / normalized scheme records ---------- */
export const SCHEMES = RAW_SCHEMES.map(s => ({
  scheme_id: s.scheme_id,
  scheme_name: s.scheme_name,
  category: s.category,
  target_gender: s.target_gender,
  max_project_cost_inr: s.max_project_cost_inr === "" ? null : Number(s.max_project_cost_inr),
  max_loan_limit_inr: s.max_loan_limit_inr === "" ? null : Number(s.max_loan_limit_inr),
  loan_percentage_cap: s.loan_percentage_cap === "" ? null : Number(s.loan_percentage_cap),
  interest_rate_male_pct: s.interest_rate_male_pct === "" ? null : s.interest_rate_male_pct,
  interest_rate_female_pct: s.interest_rate_female_pct === "" ? null : s.interest_rate_female_pct,
  interest_rate_conditional_logic: s.interest_rate_conditional_logic || null,
  max_repayment_period_months: s.max_repayment_period_months,
  moratorium_period_months: s.moratorium_period_months,
  allowed_channel_partners: s.allowed_channel_partners,
  // These fields are not present in the source CSV -- explicitly marked
  active: true, // no deactivation flag in source; all treated as currently listed/active
  source_authority: "NSFDC Scheme Master (uploaded CSV)",
  last_verified: "2026-09-04",
  last_updated: "2026-09-04",
}));

/* ---------- Derived / normalized partner records ---------- */
export const PARTNERS = RAW_PARTNERS.map(p => ({
  ...p,
  // active_status in source is literally "UNKNOWN" for all rows -- preserve, don't invent
  active_status: p.active_status || "UNKNOWN",
  location_status: p.location_status || "MISSING_NEEDS_PARTNER_LOCATION",
  has_location: p.partner_location_latitude != null && p.partner_location_longitude != null,
  overdue_ratio: null, // not present anywhere in source dataset
  admin_status_override: null, // admin-settable status layered on top of source active_status
}));

export const PARTNER_TYPES = [...new Set(PARTNERS.map(p => p.partner_type))].sort();
export const STATES = [...new Set(PARTNERS.map(p => p.state))].sort();

